import { existsSync, readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'

// AC-B1: hacked-media fixtures exist (generated by tests/fixtures/hacked-media/generate.mjs) and stay inert.
const NAMES = [
  'logo.jpg.php', 'shell.phtml', 'polyglot.jpg', 'scripted.svg', 'js.pdf', 'fake.png', 'exif-gps.jpg',
  'ok.jpg', 'ok.png', 'ok.gif', 'ok.webp', 'ok.pdf', 'ok.mp4', 'ok.mp3',
]
const path = (n: string) => new URL(`../fixtures/hacked-media/${n}`, import.meta.url)

describe('hacked-media fixtures (AC-B1)', () => {
  it.each(NAMES)('%s exists and is small', (n) => {
    expect(existsSync(path(n))).toBe(true)
    expect(readFileSync(path(n)).length).toBeLessThan(4096)
  })

  it('attack samples are inert: PHP only echoes, scripts only alert', () => {
    for (const n of ['logo.jpg.php', 'shell.phtml', 'polyglot.jpg']) {
      const s = readFileSync(path(n), 'latin1')
      for (const m of s.matchAll(/<\?php(.*?)\?>/g)) expect(m[1]?.trim()).toBe('echo "x";')
    }
    expect(readFileSync(path('scripted.svg'), 'utf8')).toMatch(/<script>alert\(1\)<\/script>/)
    expect(readFileSync(path('js.pdf'), 'latin1')).toContain(String.raw`/JS (app.alert\(1\))`)
  })
})
